# Analyze each transformation
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find differences character by character
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(outp) > len(inp):
        # Added characters
        for j in range(len(inp), len(outp)):
            diff_positions.append((j, '-', outp[j]))
    elif len(inp) > len(outp):
        # Removed characters  
        for j in range(len(outp), len(inp)):
            diff_positions.append((j, inp[j], '-'))

    print(f"  Differences: {diff_positions}")
    print()

